h1 { font-size:48px; line-height:1.13; font-weight:900; margin-bottom:16px; }
.hero-sub { font-size:18px; color:rgba(255,255,255,.88); margin-bottom:28px; max-width:560px; }
.btn {
  display:inline-flex; align-items:center; padding:14px 24px; border-radius:999px;
  text-decoration:none; font-weight:900; font-size:15px; transition:.25s ease; border:none; cursor:pointer;
}
.btn-primary { background:linear-gradient(135deg,var(--orange),#ff9e3d); color:#fff; box-shadow:0 12px 28px rgba(242,140,40,.35); }
.btn-danger { background:linear-gradient(135deg,#d33b3b,#b91c1c); color:#fff; box-shadow:0 12px 28px rgba(185,28,28,.28); }
.btn-danger:hover { transform:translateY(-2px); }
.member-note { display:inline-block; margin-top:8px; padding:6px 10px; border-radius:999px; font-size:12px; font-weight:800; color:#b91c1c; background:rgba(185,28,28,.08); border:1px solid rgba(185,28,28,.16); }
.modal-overlay { position:fixed; inset:0; background:rgba(11,39,66,.62); display:none; align-items:center; justify-content:center; padding:20px; z-index:9999; }
.modal-overlay.active { display:flex; }
.modal-box { width:min(460px, 100%); background:#fff; border-radius:22px; padding:28px 24px; box-shadow:0 24px 60px rgba(0,0,0,.22); text-align:center; }
.modal-box h3 { color:var(--blue-deep); font-size:24px; font-weight:900; margin-bottom:10px; }
.modal-box p { color:var(--muted); font-size:15px; line-height:1.8; margin-bottom:18px; }
.modal-actions { display:flex; gap:12px; justify-content:center; flex-wrap:wrap; }
.modal-actions .btn { min-width:140px; }
body.modal-open { overflow:hidden; }
@media(max-width:768px){ .modal-actions .btn { width:100%; } }
.btn-secondary { color:#fff; border:1px solid rgba(255,255,255,.28); background:rgba(255,255,255,.07); }
.btn:hover { transform:translateY(-2px); }
.cta-row { display:flex; flex-wrap:wrap; gap:12px; }
.hero-note { margin-top:12px; font-size:13px; color:rgba(255,255,255,.7); }

